158	export function joined(...parts: Uint8Array[]): Uint8Array {
159	  const out = new Uint8Array(parts.reduce((n, p) => n + p.length, 0));
160	  let at = 0;
161	  for (const part of parts) {
162	    out.set(part, at);
163	    at += part.length;
164	  }
165	  return out;
