  1	/**
  2	 * A Stream Deck profile built from a pack, in Node or in a browser.
  3	 *
  4	 * `streamdeck/design/profiles.mjs` runs this over the packs in the
  5	 * repository and commits the forty-four files the plugin ships. A pack
  6	 * from the Marketplace is not known when the plugin is packed, so its own
  7	 * page runs the same code on the pack it is showing and hands over the
  8	 * bytes. Nothing here touches the filesystem or a Node built-in, which is
  9	 * what lets both callers be the same code rather than two that drift.
 10	 */
 11	
 12	export { BASE, DEVICE_IDS, DEVICES, DIALS, isWarp, type Device, type DeviceId, type Key } from "./layouts.ts";
 13	export { ACTION_NAMES, PAGE_PLUGIN, PLUGIN, TURNS } from "./plugin.ts";
 14	export {
 15	  container,
 16	  GENERIC,
 17	  hasKeys,
 18	  packKeys,
 19	  paginate,
 20	  profile,
 21	  specs,
 22	  stableId,
 23	  type Built,
 24	  type Controller,
 25	  type Page,
 26	  type PageFile,
 27	  type ProfileSpec,
 28	  type RootFile,
 29	  type StoredAction,
 30	} from "./profiles.ts";
 31	export { zip, type ZipEntry } from "./zip.ts";
 32	/**
 33	 * Who the plugin says it is, in the blocks a profile carries.
 34	 *
 35	 * Every action stored in a profile names the plugin that owns it and
 36	 * carries the label the Stream Deck app shows beside it, and both come out
 37	 * of `streamdeck/com.scrthq.runlog.sdPlugin/manifest.json`. The generator
 38	 * used to read that file. A browser building a profile for a Marketplace
 39	 * pack has no file to read, so the same handful of strings is written here
 40	 * and `plugin.test.ts` holds them against the manifest: a rename or a
 41	 * version bump over there fails that test, which is the prompt to change
 42	 * this and regenerate the committed profiles, exactly as a layout change
 43	 * would be.
 44	 */
 45	
 46	/** The plugin block every one of our actions carries. */
 47	export const PLUGIN = { Name: "Runlog", UUID: "com.scrthq.runlog", Version: "0.1.0.0" };
 48	
 49	/** The `Name` the app expects beside each of our actions, by the action's short name. */
 50	export const ACTION_NAMES: Record<string, string> = {
 51	  next: "Next action",
 52	  press: "Press",
 53	  roll: "Roll",
 54	  undo: "Undo",
 55	  run: "Run",
 56	  connect: "Connect",
 57	  metric: "Metric",
 58	  setup: "Apply setup",
 59	  command: "Command",
 60	  open: "Open in the browser",
 61	  clock: "Clock",
 62	  autoroll: "Keep rolling for me",
 63	  finish: "Finish the run",
 64	};
 65	
 66	/** The app's own page turns, which are not ours and take none of our furniture. */
 67	export const PAGE_PLUGIN = { Name: "Pages", UUID: "com.elgato.streamdeck.page", Version: "1.0" };
 68	
 69	export const TURNS = {
 70	  next: { Name: "Next Page", UUID: "com.elgato.streamdeck.page.next" },
 71	  previous: { Name: "Previous Page", UUID: "com.elgato.streamdeck.page.previous" },
 72	};
 73	/**
 74	 * SHA-1, written out here rather than imported.
 75	 *
 76	 * The profile ids are a version 5 UUID, and version 5 is SHA-1 by
 77	 * definition: change the digest and every id in every committed profile
 78	 * changes with it. Node has one in `node:crypto` and a browser has one
 79	 * behind `crypto.subtle`, but `subtle.digest` is a promise and this is
 80	 * called once per key on a deck, so the browser path would have to be
 81	 * async all the way up for a hash of forty bytes. Forty lines of it here
 82	 * keeps the whole generator synchronous and identical on both sides.
 83	 *
 84	 * Not for anything that has to be secure. SHA-1 is not, and nothing here
 85	 * is guarding anything: it is a naming scheme that has to give the same
 86	 * answer twice.
 87	 */
 88	
 89	const K = [0x5a827999, 0x6ed9eba1, 0x8f1bbcdc, 0xca62c1d6];
 90	
 91	/** The digest of one message, as its twenty bytes. */
 92	export function sha1(message: Uint8Array): Uint8Array {
 93	  // The padding the standard asks for: a 1 bit, zeros, and the length in
 94	  // bits as a 64-bit big-endian number in the last eight bytes.
 95	  const blocks = Math.ceil((message.length + 9) / 64);
 96	  const padded = new Uint8Array(blocks * 64);
 97	  padded.set(message);
 98	  padded[message.length] = 0x80;
 99	  const bits = message.length * 8;
100	  const read = new DataView(padded.buffer);
101	  read.setUint32(padded.length - 8, Math.floor(bits / 0x100000000));
102	  read.setUint32(padded.length - 4, bits >>> 0);
103	
104	  let h0 = 0x67452301;
105	  let h1 = 0xefcdab89;
106	  let h2 = 0x98badcfe;
107	  let h3 = 0x10325476;
108	  let h4 = 0xc3d2e1f0;
109	
110	  const w = new Uint32Array(80);
111	  for (let block = 0; block < blocks; block++) {
112	    const at = block * 64;
113	    for (let t = 0; t < 16; t++) w[t] = read.getUint32(at + t * 4);
114	    for (let t = 16; t < 80; t++) {
115	      const x = w[t - 3]! ^ w[t - 8]! ^ w[t - 14]! ^ w[t - 16]!;
116	      w[t] = (x << 1) | (x >>> 31);
117	    }
118	
119	    let a = h0;
120	    let b = h1;
121	    let c = h2;
122	    let d = h3;
123	    let e = h4;
124	    for (let t = 0; t < 80; t++) {
125	      const round = Math.floor(t / 20);
126	      const f = round === 0 ? (b & c) | (~b & d) : round === 2 ? (b & c) | (b & d) | (c & d) : b ^ c ^ d;
127	      const next = (((a << 5) | (a >>> 27)) + f + e + K[round]! + w[t]!) >>> 0;
128	      e = d;
129	      d = c;
130	      c = (b << 30) | (b >>> 2);
131	      b = a;
132	      a = next;
133	    }
134	
135	    h0 = (h0 + a) >>> 0;
136	    h1 = (h1 + b) >>> 0;
137	    h2 = (h2 + c) >>> 0;
138	    h3 = (h3 + d) >>> 0;
139	    h4 = (h4 + e) >>> 0;
140	  }
141	
142	  const out = new Uint8Array(20);
143	  const write = new DataView(out.buffer);
144	  write.setUint32(0, h0);
145	  write.setUint32(4, h1);
146	  write.setUint32(8, h2);
147	  write.setUint32(12, h3);
148	  write.setUint32(16, h4);
149	  return out;
150	}
151	
152	/** Text as its bytes, which is what everything here hashes. */
153	export function utf8(text: string): Uint8Array {
154	  return new TextEncoder().encode(text);
155	}
156	
157	/** Several runs of bytes as one, for a digest taken over more than one. */
158	export function joined(...parts: Uint8Array[]): Uint8Array {
159	  const out = new Uint8Array(parts.reduce((n, p) => n + p.length, 0));
160	  let at = 0;
161	  for (const part of parts) {
162	    out.set(part, at);
163	    at += part.length;
164	  }
165	  return out;
166	}

