  1	import { readFileSync } from "node:fs";
  2	import { fileURLToPath } from "node:url";
  3	import { describe, expect, it } from "vitest";
  4	
  5	import { ACTION_NAMES, PLUGIN } from "./plugin.ts";
  6	
  7	/**
  8	 * The plugin's own name, version and action labels, held against the
  9	 * manifest they are copied from.
 10	 *
 11	 * They are copied because a browser building a profile for a Marketplace
 12	 * pack has no manifest to read. This is the guard on that copy: rename an
 13	 * action or bump the plugin's version over there and this fails, which is
 14	 * the prompt to change `plugin.ts` and regenerate the committed profiles.
 15	 * Every one of these strings is written into every action of every
 16	 * profile, so a stale one ships on somebody's deck.
 17	 */
 18	const manifest = JSON.parse(
 19	  readFileSync(fileURLToPath(new URL("../../../streamdeck/com.scrthq.runlog.sdPlugin/manifest.json", import.meta.url)), "utf8"),
 20	) as { Name: string; UUID: string; Version: string; Actions: Array<{ UUID: string; Name: string }> };
 21	
 22	describe("what a profile says the plugin is", () => {
 23	  it("names the plugin the manifest names", () => {
 24	    expect(PLUGIN).toEqual({ Name: manifest.Name, UUID: manifest.UUID, Version: manifest.Version });
 25	  });
 26	
 27	  it("carries every action's label, and only the actions there are", () => {
 28	    const listed = Object.fromEntries(manifest.Actions.map((a) => [a.UUID.replace(`${manifest.UUID}.`, ""), a.Name]));
 29	    expect(ACTION_NAMES).toEqual(listed);
 30	  });
 31	});
 32	import { createHash, randomBytes } from "node:crypto";
 33	import { describe, expect, it } from "vitest";
 34	
 35	import { sha1, utf8 } from "./sha1.ts";
 36	
 37	/**
 38	 * The hand-written digest, held against the one Node ships.
 39	 *
 40	 * It is here because a browser cannot call `node:crypto` and
 41	 * `crypto.subtle` is async, not because anything was wrong with Node's. So
 42	 * the test that matters is that the two agree, on the short strings the
 43	 * ids are made of and on lengths either side of a block boundary, where a
 44	 * padding mistake hides.
 45	 */
 46	describe("sha1", () => {
 47	  const node = (bytes: Uint8Array) => new Uint8Array(createHash("sha1").update(bytes).digest());
 48	
 49	  it("agrees with node:crypto on the strings the ids are made of", () => {
 50	    for (const text of ["", "com.scrthq.runlog.profiles", "demo/xl", "elden-ring/plus/page/2/key/11", "The Long Kiln"]) {
 51	      expect([...sha1(utf8(text))], text).toEqual([...node(utf8(text))]);
 52	    }
 53	  });
 54	
 55	  it("pads right either side of a block", () => {
 56	    // 55 and 56 bytes are where the length no longer fits in the first
 57	    // block and a second one has to be added; 64 and 119 are the same
 58	    // edge one block along.
 59	    for (const length of [0, 1, 54, 55, 56, 57, 63, 64, 65, 119, 120, 128, 1000]) {
 60	      const bytes = new Uint8Array(randomBytes(length));
 61	      expect([...sha1(bytes)], `${length} bytes`).toEqual([...node(bytes)]);
 62	    }
 63	  });
 64	});
 65	import { joined, utf8 } from "./sha1.ts";
 66	
 67	/**
 68	 * The container a `.streamDeckProfile` is: a stored-only zip, written here
 69	 * rather than pulled in.
 70	 *
 71	 * Nothing else in the repository zips anything, and the alternative is a
 72	 * dependency for two hundred lines of header. Stored rather than deflated
 73	 * because a profile is a few kilobytes of JSON and the app reads either;
 74	 * every timestamp is the same fixed one, so running this twice produces the
 75	 * same bytes twice and the committed files only move when a layout does.
 76	 *
 77	 * Bytes rather than Buffers, so the same writer runs in a browser.
 78	 */
 79	
 80	const CRC = (() => {
 81	  const table = new Int32Array(256);
 82	  for (let n = 0; n < 256; n++) {
 83	    let c = n;
 84	    for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
 85	    table[n] = c;
 86	  }
 87	  return table;
 88	})();
 89	
 90	function crc32(bytes: Uint8Array): number {
 91	  let c = ~0;
 92	  for (const b of bytes) c = CRC[(c ^ b) & 0xff]! ^ (c >>> 8);
 93	  return ~c >>> 0;
 94	}
 95	
 96	/** One thing in the archive. A folder is a name ending in `/` and no body. */
 97	export interface ZipEntry {
 98	  name: string;
 99	  data?: Uint8Array;
100	}
101	
102	export function zip(entries: ZipEntry[]): Uint8Array {
103	  const DOS_DATE = 33; // 1980-01-01, the earliest a zip can say.
104	  const parts: Uint8Array[] = [];
105	  const central: Uint8Array[] = [];
106	  let offset = 0;
107	  for (const { name, data } of entries) {
108	    const label = utf8(name);
109	    const body = data ?? new Uint8Array(0);
110	    const sum = crc32(body);
111	
112	    const head = new Uint8Array(30);
113	    const headAt = new DataView(head.buffer);
114	    headAt.setUint32(0, 0x04034b50, true);
115	    headAt.setUint16(4, 20, true);
116	    headAt.setUint16(12, DOS_DATE, true);
117	    headAt.setUint32(14, sum, true);
118	    headAt.setUint32(18, body.length, true);
119	    headAt.setUint32(22, body.length, true);
120	    headAt.setUint16(26, label.length, true);
121	    parts.push(head, label, body);
122	
123	    const listed = new Uint8Array(46);
124	    const listedAt = new DataView(listed.buffer);
125	    listedAt.setUint32(0, 0x02014b50, true);
126	    listedAt.setUint16(4, 20, true);
127	    listedAt.setUint16(6, 20, true);
128	    listedAt.setUint16(14, DOS_DATE, true);
129	    listedAt.setUint32(16, sum, true);
130	    listedAt.setUint32(20, body.length, true);
131	    listedAt.setUint32(24, body.length, true);
132	    listedAt.setUint16(28, label.length, true);
133	    // The directory bit, so an unpacker makes the folder rather than a file.
134	    listedAt.setUint32(38, name.endsWith("/") ? 0x10 : 0, true);
135	    listedAt.setUint32(42, offset, true);
136	    central.push(listed, label);
137	
138	    offset += head.length + label.length + body.length;
139	  }
140	
141	  const directory = joined(...central);
142	  const end = new Uint8Array(22);
143	  const endAt = new DataView(end.buffer);
144	  endAt.setUint32(0, 0x06054b50, true);
145	  endAt.setUint16(8, entries.length, true);
146	  endAt.setUint16(10, entries.length, true);
147	  endAt.setUint32(12, directory.length, true);
148	  endAt.setUint32(16, offset, true);
149	  return joined(...parts, directory, end);
150	}

