  1	import type { Pack, Setup } from "@runlog/rules-schema";
  2	
  3	import { BASE, DEVICE_IDS, DEVICES, DIALS, isWarp, type DeviceId, type Key } from "./layouts.ts";
  4	import { ACTION_NAMES, PAGE_PLUGIN, PLUGIN, TURNS } from "./plugin.ts";
  5	import { joined, sha1, utf8 } from "./sha1.ts";
  6	import { zip, type ZipEntry } from "./zip.ts";
  7	
  8	/**
  9	 * A deck laid out for a pack: its moves on keys, its counters and
 10	 * resources on the numbers, and the setups for its tool ready to hand out.
 11	 *
 12	 * Nothing is typed in here. The ids come off the pack, so a renamed move
 13	 * changes the profile next time one is built rather than going quietly
 14	 * dead on somebody's deck. The plugin ships forty-four of these built by
 15	 * `streamdeck/design/profiles.mjs` and committed; a Marketplace pack is
 16	 * not known when the plugin is packed, so its own page builds one in the
 17	 * browser from this same code.
 18	 *
 19	 * The container is a zip whose single top-level entry is a
