209	 * every page with more behind it spends its last on a way on. The last page
210	 * spends neither, so a layout that fits exactly does not grow a turn key
211	 * pointing at nothing.
212	 */
213	export function paginate(keys: Key[], capacity: number): Page[] {
214	  const pages: Page[] = [];
215	  let i = 0;
216	  while (i < keys.length) {
217	    const back = pages.length > 0 ? 1 : 0;
218	    let room = capacity - back;
219	    const more = keys.length - i > room;
220	    if (more) room -= 1;
221	    pages.push({ back: back === 1, more, keys: keys.slice(i, i + room) });
