237	export function profile({ slug, device, name, keys }: ProfileSpec, ids: (name: string) => string = stableId): Built {
238	  const { model, columns, rows, dials } = DEVICES[device];
239	  const capacity = columns * rows;
240	  const cut = paginate(keys, capacity);
241	
242	  const files: Record<string, PageFile | RootFile> = {};
243	  const pageIds: string[] = [];
244	  for (const [index, page] of cut.entries()) {
245	    const id = ids(`${slug}/${device}/page/${index}`).toUpperCase();
246	    pageIds.push(id);
