289	/** A built profile as the bytes of a `.streamDeckProfile`, folders and all. */
290	export function container({ folder, files }: Built): Uint8Array {
291	  const entries: ZipEntry[] = [{ name: `${folder}/` }];
292	  const folders = new Set<string>();
293	  for (const path of Object.keys(files)) {
294	    const parts = path.split("/").slice(0, -1);
295	    for (let i = 1; i <= parts.length; i++) folders.add(parts.slice(0, i).join("/"));
296	  }
297	  for (const dir of [...folders].sort()) entries.push({ name: `${folder}/${dir}/` });
298	  for (const [path, body] of Object.entries(files)) {
299	    entries.push({ name: `${folder}/${path}`, data: utf8(JSON.stringify(body)) });
300	  }
301	  return zip(entries);
302	}
