308	 * it is playing. The slug a profile takes here is the pack's own id, which
309	 * is what a download from a pack's page is named after; the shipped
310	 * forty-four are written under the short slugs their files are named by,
311	 * so `design/profiles.mjs` puts its own slug on each spec before building.
312	 */
313	export function specs(pack: Pack | null, setups: Setup[], device?: DeviceId): ProfileSpec[] {
314	  const keys = pack ? [...BASE, ...packKeys(pack, setups)] : [...BASE];
315	  const slug = pack ? pack.id : GENERIC.slug;
316	  const name = pack ? pack.title : GENERIC.name;
317	  return (device ? [device] : DEVICE_IDS).map((d) => ({ slug, device: d, name, keys }));
318	}

