254	    if (page.more) actions[at(capacity - 1, columns)] = turn(ids(`${slug}/${device}/page/${index}/more`), "next");
255	
256	    const controllers: Controller[] = [{ Type: "Keypad", Actions: actions }];
257	    if (dials > 0) {
258	      const wheel: Record<string, StoredAction> = {};
259	      for (const [n, dial] of DIALS.slice(0, dials).entries()) {
260	        wheel[`${n},0`] = entry(ids(`${slug}/${device}/page/${index}/dial/${n}`), dial);
261	      }
262	      controllers.push({ Type: "Encoder", Actions: wheel });
263	    }
264	    files[`Profiles/${id}/manifest.json`] = { Controllers: controllers, Icon: "", Name: "" };
265	  }
266	
267	  // The default page is the empty one the app falls back to. It is not in
268	  // `Pages`, which is why a profile with one page still lists two folders.
269	  const empty = ids(`${slug}/${device}/default`).toUpperCase();
270	  files[`Profiles/${empty}/manifest.json`] = { Controllers: [{ Actions: null, Type: "Keypad" }], Icon: "", Name: "" };
271	
272	  files["manifest.json"] = {
273	    // Empty, and it has to be: the serial that sits here in a profile the
274	    // app wrote is one particular deck on one particular desk, and a
275	    // profile we hand out goes to everybody's.
276	    Device: { Model: model, UUID: "" },
277	    Name: name,
278	    Pages: {
279	      Current: pageIds[0]!.toLowerCase(),
280	      Default: empty.toLowerCase(),
281	      Pages: pageIds.map((id) => id.toLowerCase()),
282	    },
283	    Version: "3.0",
284	  };
285	
286	  return { folder: `${ids(`${slug}/${device}`).toUpperCase()}.sdProfile`, files };
287	}
288	
289	/** A built profile as the bytes of a `.streamDeckProfile`, folders and all. */
290	export function container({ folder, files }: Built): Uint8Array {
291	  const entries: ZipEntry[] = [{ name: `${folder}/` }];
292	  const folders = new Set<string>();
293	  for (const path of Object.keys(files)) {
294	    const parts = path.split("/").slice(0, -1);
295	    for (let i = 1; i <= parts.length; i++) folders.add(parts.slice(0, i).join("/"));
296	  }
297	  for (const dir of [...folders].sort()) entries.push({ name: `${folder}/${dir}/` });
298	  for (const [path, body] of Object.entries(files)) {
299	    entries.push({ name: `${folder}/${path}`, data: utf8(JSON.stringify(body)) });
300	  }
301	  return zip(entries);
302	}
303	
304	/**
305	 * The profiles for one pack, one per deck, or just the deck named.
306	 *
307	 * `pack` null is the generic layout: the keys any run wants, whatever pack
308	 * it is playing. The slug a profile takes here is the pack's own id, which
309	 * is what a download from a pack's page is named after; the shipped
310	 * forty-four are written under the short slugs their files are named by,
311	 * so `design/profiles.mjs` puts its own slug on each spec before building.
312	 */
313	export function specs(pack: Pack | null, setups: Setup[], device?: DeviceId): ProfileSpec[] {
314	  const keys = pack ? [...BASE, ...packKeys(pack, setups)] : [...BASE];
315	  const slug = pack ? pack.id : GENERIC.slug;
316	  const name = pack ? pack.title : GENERIC.name;
317	  return (device ? [device] : DEVICE_IDS).map((d) => ({ slug, device: d, name, keys }));
318	}

