 1	import { useRef, useState } from "react";
 2	import { loadPackText, type Pack } from "@runlog/rules-schema";
 3	import { DEVICES, DEVICE_IDS, container, hasKeys, profile, specs, type DeviceId } from "@runlog/deck-profiles";
 4	import { builtins } from "../control/builtin.ts";
 5	import { forTool, setupsHere } from "../control/setups.ts";
 6	import { useDismiss } from "../ui/useDismiss.ts";
 7	
 8	/**
 9	 * A Stream Deck profile for this pack, built here and downloaded.
10	 *
11	 * The plugin ships a profile for every pack in the repository, laid out by
12	 * `streamdeck/design/profiles.mjs` and committed. A pack from the
13	 * Marketplace was not there when the plugin was packed, so its own page
14	 * runs the same generator, `@runlog/deck-profiles`, on the pack it is
15	 * showing: its moves on keys, its counters and resources on the numbers,
16	 * and the setups for whatever tool drives it ready to hand out. What comes
17	 * out is the same `.streamDeckProfile` the plugin would have shipped, to be
18	 * imported once in the Stream Deck app.
19	 *
20	 * The pack's text is read when somebody opens this rather than when the
21	 * card is drawn. A marketplace listing's text comes over the network, and
22	 * fetching twenty packs to decide whether to draw twenty rows nobody asked
23	 * for is a page that costs what it does not spend.
24	 */
25	export function DeckProfiles({ load }: { load: () => Promise<string> }) {
26	  const [open, setOpen] = useState(false);
27	  const root = useRef<HTMLDetailsElement>(null);
28	  const [pack, setPack] = useState<Pack | null>(null);
29	  /** Set once the pack has been read and has nothing of its own to lay out. */
30	  const [nothing, setNothing] = useState(false);
31	  const [busy, setBusy] = useState<DeviceId | null>(null);
32	  useDismiss(root, open, () => setOpen(false));
33	
34	  if (nothing) return null;
35	
36	  const read = async () => {
37	    if (pack) return;
38	    try {
39	      const parsed = loadPackText(await load(), "yaml");
40	      if (parsed.ok && hasKeys(parsed.pack)) setPack(parsed.pack);
41	      else setNothing(true);
42	    } catch {
43	      // Nothing to read: a priced listing, or a fetch that did not answer.
44	      setNothing(true);
45	    }
46	  };
47	
48	  const download = async (device: DeviceId) => {
49	    if (!pack) return;
50	    setBusy(device);
51	    try {
52	      // The tool is the pack's, from the control profile written for it;
53	      // the setups are the tool's, because a setup names a tool and no pack
54	      // at all. A pack nothing is written for gets no setup keys.
55	      const tool = (await builtins()).find((b) => b.pack === pack.id)?.profile.tool;
56	      const setups = forTool(await setupsHere(), tool);
57	      const bytes = container(profile(specs(pack, setups, device)[0]!));
58	      const url = URL.createObjectURL(new Blob([bytes as BlobPart], { type: "application/zip" }));
59	      const a = document.createElement("a");
60	      a.href = url;
61	      a.download = `${pack.id}-${device}.streamDeckProfile`;
62	      a.click();
63	      // The object URL must outlive the download the click started.
64	      setTimeout(() => URL.revokeObjectURL(url), 10_000);
65	    } finally {
66	      setBusy(null);
67	    }
68	  };
69	
70	  return (
71	    <details
72	      ref={root}
73	      className="rowMenu deckProfiles"
74	      open={open}
75	      onToggle={(e) => {
76	        setOpen(e.currentTarget.open);
77	        if (e.currentTarget.open) void read();
78	      }}
79	    >
80	      <summary title="A profile for your Stream Deck, laid out from this pack">Stream Deck profile</summary>
81	      <div className="rowMenuPanel">
82	        {pack === null ? (
83	          <p className="muted small">Loading…</p>
84	        ) : (
85	          <>
86	            <p className="muted small">Import the file in the Stream Deck app.</p>
87	            <div className="options">
88	              {DEVICE_IDS.map((device) => (
89	                <button key={device} className="chip pick" disabled={busy !== null} onClick={() => void download(device)}>
90	                  {DEVICES[device].label}
91	                </button>
92	              ))}
93	            </div>
94	          </>
95	        )}
96	      </div>
97	    </details>
98	  );
99	}

