 1	// @vitest-environment jsdom
 2	import { afterEach, describe, expect, it, vi } from "vitest";
 3	import { cleanup, fireEvent, render, screen, waitFor } from "@testing-library/react";
 4	import YAML from "yaml";
 5	import demo from "../../../../packs/demo/pack.yaml?raw";
 6	import { DeckProfiles } from "./DeckProfiles.tsx";
 7	
 8	/**
 9	 * The download a pack's own page offers.
10	 *
11	 * What comes out of the builder is held against the profiles the plugin
12	 * ships in `packages/deck-profiles`, byte for byte, so what is checked here
13	 * is the other half: that the row asks for the pack only when somebody
14	 * opens it, that a pack with nothing of its own to lay out draws no row at
15	 * all, and that pressing a deck gets as far as handing the browser a file.
16	 * jsdom has no `URL.createObjectURL`, so it is stood in for; without it the
17	 * press would throw and the test would be about jsdom rather than this.
18	 */
19	
20	afterEach(cleanup);
21	
22	/** The demo pack with its moves, counters and resources taken out. */
23	const bare = YAML.stringify({ ...(YAML.parse(demo) as object), counters: undefined, resources: undefined, moves: undefined });
24	
25	/** Stand in for the object URLs jsdom does not make, and say what was asked of them. */
26	function objectUrls(): string[] {
27	  const made: string[] = [];
28	  Object.assign(URL, {
29	    createObjectURL: (blob: Blob) => {
30	      made.push(blob.type);
31	      return "blob:deck";
32	    },
33	    revokeObjectURL: () => {},
34	  });
35	  return made;
36	}
37	
38	/** Open the row, the way a reader does. */
39	const open = () => fireEvent.click(screen.getByText("Stream Deck profile"));
40	
41	describe("a Stream Deck profile from a pack's page", () => {
42	  it("does not read the pack until somebody opens the row", async () => {
43	    const load = vi.fn(async () => demo);
44	    render(<DeckProfiles load={load} />);
45	    expect(load).not.toHaveBeenCalled();
46	    open();
47	    await waitFor(() => expect(load).toHaveBeenCalledTimes(1));
48	  });
49	
50	  it("offers one download per deck", async () => {
51	    render(<DeckProfiles load={async () => demo} />);
52	    open();
53	    await waitFor(() => screen.getByRole("button", { name: "XL" }));
54	    for (const label of ["XL", "Stream Deck", "Mini", "+"]) expect(screen.getByRole("button", { name: label })).toBeTruthy();
55	  });
56	
57	  it("builds the file and hands it to the browser", async () => {
58	    const made = objectUrls();
59	    const clicks: string[] = [];
60	    const press = vi.spyOn(HTMLAnchorElement.prototype, "click").mockImplementation(function (this: HTMLAnchorElement) {
61	      clicks.push(this.download);
62	    });
63	    try {
64	      render(<DeckProfiles load={async () => demo} />);
65	      open();
66	      await waitFor(() => screen.getByRole("button", { name: "Mini" }));
67	      fireEvent.click(screen.getByRole("button", { name: "Mini" }));
68	      await waitFor(() => expect(clicks).toEqual(["com.scrthq.runlog.long-kiln-mini.streamDeckProfile"]));
69	      expect(made).toEqual(["application/zip"]);
70	    } finally {
71	      press.mockRestore();
72	    }
73	  });
74	
75	  it("draws nothing for a pack with nothing of its own to lay out", async () => {
76	    const { container } = render(<DeckProfiles load={async () => bare} />);
77	    open();
78	    await waitFor(() => expect(container.innerHTML).toBe(""));
79	  });
80	});

