50	  it("offers one download per deck", async () => {
51	    render(<DeckProfiles load={async () => demo} />);
52	    open();
53	    await waitFor(() => screen.getByRole("button", { name: "XL" }));
54	    for (const label of ["XL", "Stream Deck", "Mini", "+"]) expect(screen.getByRole("button", { name: label })).toBeTruthy();
