56	
57	  it("builds the file and hands it to the browser", async () => {
58	    const made = objectUrls();
59	    const clicks: string[] = [];
60	    const press = vi.spyOn(HTMLAnchorElement.prototype, "click").mockImplementation(function (this: HTMLAnchorElement) {
61	      clicks.push(this.download);
62	    });
63	    try {
64	      render(<DeckProfiles load={async () => demo} />);
65	      open();
66	      await waitFor(() => screen.getByRole("button", { name: "Mini" }));
67	      fireEvent.click(screen.getByRole("button", { name: "Mini" }));
68	      await waitFor(() => expect(clicks).toEqual(["com.scrthq.runlog.long-kiln-mini.streamDeckProfile"]));
69	      expect(made).toEqual(["application/zip"]);
70	    } finally {
71	      press.mockRestore();
72	    }
73	  });
74	
75	  it("draws nothing for a pack with nothing of its own to lay out", async () => {
76	    const { container } = render(<DeckProfiles load={async () => bare} />);
77	    open();
78	    await waitFor(() => expect(container.innerHTML).toBe(""));
79	  });
