 12	 * has to fit on.
 13	 *
 14	 * Nobody reads a `.streamDeckProfile`. It is a zip of compact JSON that
 15	 * goes out with a release or off a pack's page and turns up on somebody's
 16	 * desk, and the two ways it goes wrong, a key off the edge of a Mini and a
 17	 * move whose id the pack renamed last month, both look to whoever imported
 18	 * it like the plugin being broken. So the layout is held to the grid and to
 19	 * the pack here, where a mistake costs a test run rather than a support
 20	 * thread.
 21	 *
 22	 * The last and largest check is that this package rebuilds the forty-four
 23	 * files committed under the plugin, byte for byte. Those are generated by
 24	 * `streamdeck/design/profiles.mjs`, which is a Node script over this code;
 25	 * proving the package alone reproduces them is what says a browser
 26	 * building a profile for a Marketplace pack is building the same thing.
 27	 */
 28	
 29	const repo = new URL("../../../", import.meta.url);
 30	const path = (rest: string) => fileURLToPath(new URL(rest, repo));
 31	
 32	/** Every setup written for a tool, by title, the way the app's picker lists them. */
 33	function setupsFor(tool: string | undefined): Setup[] {
 34	  if (!tool) return [];
 35	  const dir = path("packs/setups");
 36	  const out: Setup[] = [];
 37	  for (const file of readdirSync(dir).filter((f) => f.endsWith(".yaml"))) {
 38	    const parsed = loadSetupText(readFileSync(`${dir}/${file}`, "utf8"), "yaml");
 39	    if (parsed.ok && parsed.setup.tool.toLowerCase() === tool.toLowerCase()) out.push(parsed.setup);
 40	  }
 41	  return out.sort((a, b) => a.title.localeCompare(b.title));
 42	}
 43	
 44	/** The tool a pack is driven by, from the control profile written for it. */
 45	function toolFor(packId: string): string | undefined {
 46	  const dir = path("packs/profiles");
 47	  for (const file of readdirSync(dir).filter((f) => f.endsWith(".json"))) {
 48	    const written = JSON.parse(readFileSync(`${dir}/${file}`, "utf8")) as { pack?: string; tool?: string };
 49	    if (written.pack === packId) return written.tool;
 50	  }
 51	  return undefined;
 52	}
 53	
 54	/**
 55	 * The layouts the plugin ships, read the way the generator reads them.
 56	 *
 57	 * The slug each pack ships under comes from `streamdeck/src/profiles.ts`,
 58	 * the table the generator writes and the plugin switches through, rather
 59	 * than from a second copy of the naming rule kept here.
 60	 */
 61	const shipped: Array<{ slug: string; pack: Pack | null; setups: Setup[] }> = [{ slug: "runlog", pack: null, setups: [] }];
 62	for (const file of ["packs/demo/pack.yaml", ...readdirSync(path("packs/sketches")).map((f) => `packs/sketches/${f}`)]) {
 63	  if (!file.endsWith(".yaml")) continue;
 64	  const parsed = loadPackText(readFileSync(path(file), "utf8"), "yaml");
 65	  if (!parsed.ok) continue;
 66	  const slug = PACK_PROFILES[parsed.pack.id];
 67	  if (slug) shipped.push({ slug, pack: parsed.pack, setups: setupsFor(toolFor(parsed.pack.id)) });
 68	}
 69	
 70	/** Every layout on every deck, built, with the slug it ships under. */
 71	const all = shipped.flatMap(({ slug, pack, setups }) =>
 72	  specs(pack, setups).map((spec) => ({ spec: { ...spec, slug }, built: profile({ ...spec, slug }) })),
 73	);
 74	
 75	/** Every action on every page of a built profile, with the page and position it sits at. */
 76	function placed(built: Built): Array<{ page: string; controller: string; position: string; action: StoredAction }> {
 77	  const out = [];
 78	  for (const [page, file] of Object.entries(built.files)) {
 79	    if (!("Controllers" in file)) continue;
 80	    for (const controller of file.Controllers) {
 81	      for (const [position, action] of Object.entries(controller.Actions ?? {})) {
 82	        out.push({ page, controller: controller.Type, position, action });
 83	      }
 84	    }
 85	  }
 86	  return out;
 87	}
 88	
 89	describe("a deck laid out for a pack", () => {
 90	  it("knows how big each deck is", () => {
 91	    // Written out rather than taken from `DEVICES`, which is the table
 92	    // under test: the grid check below reads the same numbers the layout
 93	    // was built from, so without this it would pass on any pair of them.
 94	    // These are the SDK's, from the `DeviceType` enumeration in
 95	    // @elgato/schemas.
 96	    expect(DEVICES.xl).toMatchObject({ type: 2, columns: 8, rows: 4, dials: 0 });
 97	    expect(DEVICES.sd).toMatchObject({ type: 0, columns: 5, rows: 3, dials: 0 });
 98	    expect(DEVICES.mini).toMatchObject({ type: 1, columns: 3, rows: 2, dials: 0 });
 99	    expect(DEVICES.plus).toMatchObject({ type: 7, columns: 4, rows: 2, dials: 4 });
100	    expect(DEVICE_IDS).toEqual(Object.keys(DEVICES));
101	  });
102	
103	  it("keeps a page's last slot for the way on, and its first for the way back", () => {
104	    const keys = Array.from({ length: 20 }, (_, i) => ({ action: `k${i}` }));
105	    // Six to a page: five on the first with the sixth spent going on, then
106	    // four with both turns, then the rest with only the way back.
107	    expect(paginate(keys, 6).map((p) => [p.back, p.more, p.keys.length])).toEqual([
108	      [false, true, 5],
109	      [true, true, 4],
110	      [true, true, 4],
111	      [true, true, 4],
112	      [true, false, 3],
113	    ]);
114	    // A layout that fits exactly grows no turn key pointing at nothing.
115	    expect(paginate(keys.slice(0, 6), 6)).toEqual([{ back: false, more: false, keys: keys.slice(0, 6) }]);
116	  });
117	
118	  it("lays every key inside its own deck's grid", () => {
119	    for (const { spec, built } of all) {
120	      const { columns, rows, dials } = DEVICES[spec.device];
121	      for (const { controller, position } of placed(built)) {
122	        const [column, row] = position.split(",").map(Number);
123	        const width = controller === "Encoder" ? dials : columns;
124	        const height = controller === "Encoder" ? 1 : rows;
125	        expect(column, `${spec.slug}-${spec.device} ${position}`).toBeLessThan(width);
126	        expect(row, `${spec.slug}-${spec.device} ${position}`).toBeLessThan(height);
127	        expect(column).toBeGreaterThanOrEqual(0);
128	        expect(row).toBeGreaterThanOrEqual(0);
129	      }
130	    }
131	  });
132	
133	  it("puts one thing in one place", () => {
134	    for (const { spec, built } of all) {
135	      const seen = new Set<string>();
136	      for (const { page, controller, position } of placed(built)) {
137	        const where = `${page} ${controller} ${position}`;
138	        expect(seen.has(where), `${spec.slug}-${spec.device} doubles up on ${where}`).toBe(false);
139	        seen.add(where);
140	      }
141	    }
142	  });
143	
144	  it("places nothing but our own actions and the app's page turns", () => {
145	    const manifest = JSON.parse(readFileSync(path("streamdeck/com.scrthq.runlog.sdPlugin/manifest.json"), "utf8")) as {
146	      Actions: Array<{ UUID: string }>;
147	    };
148	    const allowed = new Set([
149	      ...manifest.Actions.map((a) => a.UUID),
150	      "com.elgato.streamdeck.page.next",
151	      "com.elgato.streamdeck.page.previous",
152	    ]);
153	    for (const { spec, built } of all) {
154	      for (const { action } of placed(built)) {
155	        expect(allowed.has(action.UUID), `${spec.slug}-${spec.device} places ${action.UUID}`).toBe(true);
156	      }
157	    }
158	  });
159	
160	  it("sets each key to what its own settings type allows", () => {
161	    // The shapes are `PressTarget`, `MetricField`, `SetupSettings` and
162	    // `NextSettings` in `streamdeck/src/state.ts`. A key set to something
163	    // the plugin cannot read draws "Set up" for ever and says nothing
164	    // about why.
165	    const fields = new Set(["score", "unit", "clock", "latest", "leader"]);
166	    const kinds = new Set(["roll", "move", "answer"]);
167	    for (const { spec, built } of all) {
168	      for (const { action } of placed(built)) {
169	        const settings = action.Settings;
170	        const where = `${spec.slug}-${spec.device} ${action.UUID}`;
171	        if (action.UUID === "com.scrthq.runlog.metric") {
172	          const field = settings["field"] as string | Record<string, string>;
173	          if (typeof field === "string") expect(fields.has(field), where).toBe(true);
174	          else
175	            expect(Object.keys(field), where).toSatisfy(
176	              (keys: string[]) => keys.length === 1 && ["counter", "resource"].includes(keys[0]!),
177	            );
178	        } else if (action.UUID === "com.scrthq.runlog.press") {
179	          const target = settings["target"] as { kind: string; id?: string };
180	          expect(kinds.has(target.kind), where).toBe(true);
181	          if (target.kind === "move") expect(typeof target.id, where).toBe("string");
182	        } else if (action.UUID === "com.scrthq.runlog.setup") {
183	          expect(Object.keys(settings["setup"] as object).sort(), where).toEqual(["id", "title"]);
184	        } else if (action.UUID === "com.scrthq.runlog.command") {
185	          expect(Object.keys(settings["command"] as object).sort(), where).toEqual(["id", "title"]);
186	        } else if (action.UUID === "com.scrthq.runlog.open") {
187	          expect(["run", "guide", "rules", "newrun", "dock"], where).toContain(settings["target"]);
188	        } else {
189	          expect(settings, where).toEqual({});
190	        }
191	      }
192	    }
193	  });
194	
195	  it("gives a + its dials, and no other deck one", () => {
196	    for (const { spec, built } of all) {
197	      const wheels = placed(built).filter((p) => p.controller === "Encoder");
198	      if (spec.device !== "plus") {
199	        expect(wheels, `${spec.slug}-${spec.device}`).toHaveLength(0);
200	        continue;
201	      }
202	      // Only Next, Metric and Clock declare `Encoder` in the manifest.
203	      for (const { action } of wheels) {
204	        expect(["com.scrthq.runlog.next", "com.scrthq.runlog.metric", "com.scrthq.runlog.clock"]).toContain(action.UUID);
205	      }
206	    }
207	  });
208	
209	  it("gives every profile the run and the guide, and only a pack's the rules", () => {
210	    for (const { spec, built } of all) {
211	      const targets = placed(built)
212	        .filter((p) => p.action.UUID === "com.scrthq.runlog.open")
213	        .map((p) => (p.action.Settings as { target: string }).target)
214	        .sort();
215	      expect(targets, `${spec.slug}-${spec.device}`).toEqual(spec.slug === "runlog" ? ["guide", "run"] : ["guide", "rules", "run"]);
216	    }
217	  });
218	
219	  it("carries exactly the pack's moves, its shown counters, its resources and its tool's setups", () => {
220	    // A key set to a move the pack renamed last month is dead on somebody's
221	    // deck and says nothing about why, so what is placed is held against
222	    // the pack itself rather than counted.
223	    for (const { slug, pack, setups } of shipped) {
224	      if (!pack) continue;
225	      for (const { spec, built } of all.filter((b) => b.spec.slug === slug)) {
226	        const settings = placed(built).map((p) => p.action.Settings);
227	        const where = `${spec.slug}-${spec.device}`;
228	
229	        const moves = settings.filter((s) => (s["target"] as { kind?: string } | undefined)?.kind === "move");
230	        expect(moves.map((s) => (s["target"] as { id: string }).id).sort(), where).toEqual(Object.keys(pack.moves ?? {}).sort());
231	
232	        const numbers = (which: "counter" | "resource") =>
233	          settings
234	            .filter((s) => typeof s["field"] === "object" && which in (s["field"] as object))
235	            .map((s) => (s["field"] as Record<string, string>)[which]!);
236	        const shownCounters = Object.entries(pack.counters ?? {})
237	          .filter(([, c]) => !c.hidden)
238	          .map(([id]) => id);
239	        expect(numbers("counter").sort(), where).toEqual(shownCounters.sort());
240	        expect(numbers("resource").sort(), where).toEqual(Object.keys(pack.resources ?? {}).sort());
241	
242	        const handedOut = settings
243	          .filter((s) => s["setup"] ?? s["command"])
244	          .map((s) => ((s["setup"] ?? s["command"]) as { id: string }).id);
245	        expect(handedOut.sort(), where).toEqual(setups.map((s) => s.id).sort());
246	      }
247	    }
248	  });
249	
250	  it("gives the demo pack no setup keys, because it names no tool", () => {
251	    const built = all.find(({ spec }) => spec.slug === "demo" && spec.device === "xl")!.built;
252	    expect(placed(built).filter((p) => p.action.UUID === "com.scrthq.runlog.setup")).toHaveLength(0);
253	  });
254	
255	  it("offers a deck only to a pack with something of its own to put on one", () => {
256	    const demo = shipped.find((l) => l.slug === "demo")!.pack!;
257	    expect(hasKeys(demo)).toBe(true);
258	    expect(hasKeys({ ...demo, moves: undefined, counters: undefined, resources: undefined })).toBe(false);
259	    expect(hasKeys({ ...demo, counters: undefined, resources: undefined })).toBe(true);
260	  });
261	
262	  it("names a profile after the pack, and a Marketplace one after its id", () => {
263	    // The shipped forty-four are written under the short slug their file
264	    // is named by, which the generator puts on each spec; a pack from the
265	    // Marketplace has no such file, so its id is what names the download.
266	    const demo = shipped.find((l) => l.slug === "demo")!.pack!;
267	    expect(specs(demo, [], "xl")).toEqual([{ slug: demo.id, device: "xl", name: demo.title, keys: expect.anything() }]);
268	    expect(specs(null, []).map((s) => `${s.slug}-${s.device}`)).toEqual(["runlog-xl", "runlog-sd", "runlog-mini", "runlog-plus"]);
269	  });
270	
271	  it("builds the same bytes twice, so regenerating is not a diff", () => {
272	    for (const { spec } of all) {
273	      const twice = [container(profile(spec)), container(profile(spec))];
274	      expect([...twice[0]!], `${spec.slug}-${spec.device}`).toEqual([...twice[1]!]);
275	    }
276	  });
277	
278	  it("rebuilds every profile committed under the plugin, byte for byte", () => {
279	    // A `.streamDeckProfile` is generated and committed rather than built
280	    // at install time, so a layout change nobody regenerated for leaves a
281	    // stale zip next to the source that no longer agrees with it.
282	    expect(all).toHaveLength(44);
283	    for (const { spec, built } of all) {
284	      const committed = readFileSync(path(`streamdeck/com.scrthq.runlog.sdPlugin/profiles/${spec.slug}-${spec.device}.streamDeckProfile`));
285	      expect(Buffer.from(container(built)).equals(committed), `${spec.slug}-${spec.device}`).toBe(true);
286	    }
287	  });
288	});

