     1	/**
     2	 * The profiles the plugin ships: a deck laid out before anybody touches it.
     3	 *
     4	 * Forty-four `.streamDeckProfile` files, eleven layouts across four decks.
     5	 * One is generic, the keys any run wants whatever pack it is playing, and
     6	 * the rest are written against a pack. The laying out is
     7	 * `@runlog/deck-profiles`, which is the same code a pack's Marketplace page
     8	 * runs in the browser for a pack the plugin never shipped a profile for;
     9	 * what is left here is the part that needs a filesystem. Nothing is typed
    10	 * in either: the ids come out of the pack files through the same loader the
    11	 * app and the CLI use, so a renamed move changes the profile on the next
    12	 * run of this script rather than going quietly dead on somebody's deck.
    13	 *
    14	 * `npm run profiles -w streamdeck`. It also writes `src/profiles.ts`, which
    15	 * is the one thing here the plugin reads at run time: the table that turns a
    16	 * run's pack into the profile to switch a deck to.
    17	 */
    18	import { mkdirSync, readFileSync, readdirSync, writeFileSync } from "node:fs";
    19	import { basename, dirname, join } from "node:path";
    20	import { fileURLToPath } from "node:url";
    21	
    22	import { DEVICES, container, profile, specs } from "@runlog/deck-profiles";
    23	import { loadPackText, loadSetupText } from "@runlog/rules-schema";
    24	
    25	import { DEMO, SKETCHES, SLUGS } from "./layouts.mjs";
    26	
    27	const here = dirname(fileURLToPath(import.meta.url));
    28	const plugin = join(here, "..", "com.scrthq.runlog.sdPlugin");
    29	const repo = join(here, "..", "..");
    30	
    31	/** Our own manifest, for the profile list this checks itself against. */
    32	const MANIFEST = JSON.parse(readFileSync(join(plugin, "manifest.json"), "utf8"));
    33	
    34	/** The tool a pack is driven by, from the shipped control profile written for it. */
    35	function toolFor(packId) {
    36	  const dir = join(repo, "packs", "profiles");
    37	  for (const file of readdirSync(dir).filter((f) => f.endsWith(".json"))) {
    38	    // Read as JSON rather than through the app's reader: that one wants the
    39	    // tool's operation catalog to say anything useful, and all this needs is
    40	    // two fields that `apps/web/src/control/shipped.test.ts` already holds
    41	    // every one of these files to.
    42	    const written = JSON.parse(readFileSync(join(dir, file), "utf8"));
    43	    if (written.pack === packId) return written.tool;
    44	  }
    45	  return undefined;
    46	}
    47	
    48	/** Every setup written for a tool, by title, the way the app's picker lists them. */
    49	function setupsFor(tool) {
    50	  if (!tool) return [];
    51	  const dir = join(repo, "packs", "setups");
    52	  const out = [];
    53	  for (const file of readdirSync(dir).filter((f) => f.endsWith(".yaml"))) {
    54	    const parsed = loadSetupText(readFileSync(join(dir, file), "utf8"), "yaml");
    55	    if (parsed.ok && parsed.setup.tool.toLowerCase() === tool.toLowerCase()) out.push(parsed.setup);
    56	  }
    57	  return out.sort((a, b) => a.title.localeCompare(b.title));
    58	}
    59	
    60	/**
    61	 * The layouts, in the order the manifest lists them: generic, demo, sketches.
    62	 *
    63	 * Every pack that ships gets one. Forty profiles auto-installing on a deck
    64	 * would be forty entries in somebody's profile list on the day they install
    65	 * the plugin, so a pack's four wait in the package and the plugin asks for
    66	 * the one it needs; `main` writes the table it asks through.
    67	 *
    68	 * A sketch that no longer parses is left out rather than throwing. It is a
    69	 * file in the repository with its own tests, and a broken one should fail
    70	 * there rather than stop every other profile being written.
    71	 */
    72	export function layouts() {
    73	  const sketches = readdirSync(join(repo, SKETCHES))
    74	    .filter((f) => f.endsWith(".yaml"))
    75	    .sort()
    76	    .map((f) => ({ slug: SLUGS[basename(f, ".yaml")] ?? basename(f, ".yaml"), file: `${SKETCHES}/${f}` }));
    77	
    78	  const out = [{ slug: "runlog", pack: null }];
    79	  for (const { slug, file } of [DEMO, ...sketches]) {
    80	    const parsed = loadPackText(readFileSync(join(repo, file), "utf8"), "yaml");
    81	    if (!parsed.ok) continue;
    82	    out.push({ slug, pack: parsed.pack });
    83	  }
    84	  return out;
    85	}
    86	
    87	/**
    88	 * The forty-four profiles, named and keyed, ready to be laid out on a grid.
    89	 *
    90	 * The slug is put on here rather than taken from the package: a profile
    91	 * built in the browser is named after the pack's id, and these are named
    92	 * after the file each pack is kept in, which is what they have shipped
    93	 * under since before the Marketplace had any say in it.
    94	 */
    95	export function profileSpecs() {
    96	  const out = [];
    97	  for (const layout of layouts()) {
    98	    for (const spec of specs(layout.pack, setupsFor(layout.pack ? toolFor(layout.pack.id) : undefined))) {
    99	      out.push({ ...spec, slug: layout.slug });
   100	    }
   101	  }
   102	  return out;
   103	}
   104	
   105	/**
   106	 * The table the plugin switches through, as a module it can import.
   107	 *
   108	 * The plugin never spells a profile name out. A pack renamed here, or a
   109	 * sketch added to the repository, moves this file on the next run of the
   110	 * generator, and the two stay one thing rather than two lists that drift.
   111	 */
   112	export function table(list = layouts()) {
   113	  const packs = list.filter((l) => l.pack).map((l) => `  "${l.pack.id}": "${l.slug}",`);
   114	  const decks = Object.entries(DEVICES).map(([device, { type }]) => `  ${type}: "${device}",`);
   115	  return `/**
   116	 * Which profile a run's pack is laid out in, and what each deck is called.
   117	 *
   118	 * Written by \`design/profiles.mjs\`: run \`npm run profiles -w streamdeck\`
   119	 * and commit what moves. Editing it by hand renames a profile the plugin
   120	 * asks for without renaming the file behind it, and the switch then does
   121	 * nothing at all.
   122	 */
   123	
   124	/** The slug of the profile laid out for each pack the plugin ships. */
   125	export const PACK_PROFILES: Record<string, string> = {
   126	${packs.join("\n")}
   127	};
   128	
   129	/** What a profile name calls each deck, by the SDK's \`DeviceType\`. */
   130	export const DEVICE_PROFILES: Record<number, string> = {
   131	${decks.join("\n")}
   132	};
   133	
   134	/** The layout a run gets where its pack ships none, which is every Marketplace pack. */
   135	export const GENERIC_PROFILE = "runlog";
   136	
   137	/**
   138	 * The profile to put a deck on for a run of this pack.
   139	 *
   140	 * \`null\` for a deck nothing here is laid out for - a Pedal, a Neo - which is
   141	 * a deck to leave alone rather than one to push the generic layout onto.
   142	 */
   143	export function profileFor(packId: string | undefined, device: number): string | null {
   144	  const deck = DEVICE_PROFILES[device];
   145	  if (deck === undefined) return null;
   146	  const slug = (packId === undefined ? undefined : PACK_PROFILES[packId]) ?? GENERIC_PROFILE;
   147	  return \`profiles/\${slug}-\${deck}\`;
   148	}
   149	`;
   150	}
   151	
   152	function main() {
   153	  const dir = join(plugin, "profiles");
   154	  mkdirSync(dir, { recursive: true });
   155	
   156	  const written = [];
   157	  for (const spec of profileSpecs()) {
   158	    const file = `${spec.slug}-${spec.device}`;
   159	    writeFileSync(join(dir, `${file}.streamDeckProfile`), container(profile(spec)));
   160	    // The generic four come with the plugin; a pack's four are installed the
   161	    // first time a deck follows a run of that pack.
   162	    written.push({ name: `profiles/${file}`, type: DEVICES[spec.device].type, auto: spec.slug === "runlog" });
   163	  }
   164	
   165	  writeFileSync(join(here, "..", "src", "profiles.ts"), table());
   166	
   167	  // The manifest is edited by hand - a generator that rewrites it fights the
   168	  // formatter over every other line - so the one thing checked here is that
   169	  // it still lists what was just written, in the same order.
   170	  const listed = (MANIFEST.Profiles ?? []).map((p) => `${p.Name}:${p.DeviceType}:${p.AutoInstall}`).join(" ");
   171	  const expected = written.map((p) => `${p.name}:${p.type}:${p.auto}`).join(" ");
   172	  if (listed !== expected) throw new Error(`manifest.json lists\n  ${listed}\nbut this wrote\n  ${expected}`);
   173	
   174	  console.log(`${written.length} profiles written to ${dir}`);
   175	}
   176	
   177	if (process.argv[1] === fileURLToPath(import.meta.url)) main();
