  9	
 10	/**
 11	 * The generator as a script: which packs it reads, what it writes beside
 12	 * them, and whether the manifest still lists what came out.
 13	 *
 14	 * How a profile is laid out, and whether its keys fit the deck, is
 15	 * `packages/deck-profiles` and is tested there. What is left here is the
 16	 * part that is only true of this repository: the list of packs on disk, the
 17	 * slug each ships under, the files committed under the plugin, and the
 18	 * table the plugin reads at run time.
 19	 */
 20	
 21	const here = dirname(fileURLToPath(import.meta.url));
 22	const plugin = join(here, "..", "com.scrthq.runlog.sdPlugin");
 23	const repo = join(here, "..", "..");
 24	
 25	const MANIFEST = JSON.parse(readFileSync(join(plugin, "manifest.json"), "utf8"));
 26	
 27	const all = profileSpecs().map((spec) => ({ spec, built: profile(spec) }));
 28	
 29	describe("the profiles we ship", () => {
 30	  it("lays one out for the generic keys and one for every pack that ships", () => {
 31	    // The demo pack and every sketch, by the slug each takes from its file
 32	    // name. Written out rather than read from the folder a second time: this
 33	    // is the list, and a sketch that stopped parsing would otherwise drop
 34	    // off it without a word.
 35	    expect(layouts().map((l) => l.slug)).toEqual([
 36	      "runlog",
 37	      "demo",
 38	      "elden-ring",
 39	      "forfeits",
 40	      "ladder-work",
 41	      "practice-room",
 42	      "rocket-league-ladder",
 43	      "rocket-league-showdown",
 44	      "run-of-show",
 45	      "soundclash",
 46	      "twenty-five",
 47	    ]);
 48	    const sketches = readdirSync(join(repo, SKETCHES)).filter((f) => f.endsWith(".yaml"));
 49	    expect(layouts()).toHaveLength(sketches.length + 2);
 50	    expect(all).toHaveLength(layouts().length * Object.keys(DEVICES).length);
 51	    expect(all).toHaveLength(44);
 52	  });
 53	
 54	  it("is one per pack per device, and the manifest lists every one", () => {
 55	    expect(all.map(({ spec }) => `${spec.slug}-${spec.device}`)).toEqual(MANIFEST.Profiles.map((p) => p.Name.replace("profiles/", "")));
 56	    for (const p of MANIFEST.Profiles) {
 57	      const device = p.Name.split("-").pop();
 58	      expect(p.DeviceType, `${p.Name} should be laid out for the device it names`).toBe(DEVICES[device].type);
 59	    }
 60	  });
 61	
 62	  it("installs the generic four with the plugin and a pack's four on demand", () => {
 63	    // Forty profiles arriving on the day somebody installs the plugin is a
 64	    // profile list nobody can find their own work in. A pack's four are
 65	    // installed the first time a deck follows a run of that pack, and never
 66	    // switch themselves on the way in: the plugin says when.
 67	    for (const p of MANIFEST.Profiles) {
 68	      const generic = p.Name.startsWith("profiles/runlog-");
 69	      expect(p.AutoInstall, `${p.Name}`).toBe(generic);
 70	      expect(p.DontAutoSwitchWhenInstalled, `${p.Name}`).toBe(true);
 71	    }
 72	    expect(MANIFEST.Profiles.filter((p) => p.AutoInstall)).toHaveLength(4);
 73	  });
 74	
 75	  it("hands the plugin a table of the names rather than letting it guess them", () => {
 76	    // `src/profiles.ts` is written by the generator and read at run time. If
 77	    // it is behind the packs on disk the plugin asks for a profile that is
 78	    // not in the package, and the switch does nothing anybody can see.
 79	    const written = readFileSync(join(here, "..", "src", "profiles.ts"), "utf8");
 80	    expect(written.replace(/\r\n/g, "\n")).toBe(table().replace(/\r\n/g, "\n"));
 81	    for (const layout of layouts()) {
 82	      if (layout.pack) expect(written).toContain(`"${layout.pack.id}": "${layout.slug}"`);
 83	    }
 84	  });
 85	
 86	  it("matches the profiles committed under the plugin, byte for byte", () => {
 87	    // A `.streamDeckProfile` is generated and committed rather than built at
 88	    // install time, so a layout change that nobody regenerated for leaves a
 89	    // stale zip sitting next to the source that no longer agrees with it.
 90	    for (const { spec, built } of all) {
 91	      const path = join(plugin, "profiles", `${spec.slug}-${spec.device}.streamDeckProfile`);
 92	      const committed = readFileSync(path);
 93	      expect(Buffer.from(container(built)).equals(committed), `${spec.slug}-${spec.device}`).toBe(true);
 94	    }
 95	  });
 96	
 97	  it("names each profile after the pack it was laid out from", () => {
 98	    // What the Stream Deck app calls it in somebody's list. The pack's own
 99	    // title and nothing else: the app already says which plugin a profile
100	    // came with.
101	    for (const layout of layouts()) {
102	      const named = all.filter(({ spec }) => spec.slug === layout.slug);
103	      expect(named).toHaveLength(4);
104	      for (const { built } of named) expect(built.files["manifest.json"].Name).toBe(layout.pack ? layout.pack.title : "Runlog");
105	    }
106	  });
107	
108	  it("keeps the slug Elden Ring's profile shipped under", () => {
109	    // Its file name says the tool as well as the game; its slug does not,
110	    // and changing that now would rename the profile on every deck that
111	    // already has it.
112	    expect(SLUGS["elden-ring-tarnishedtool"]).toBe("elden-ring");
113	    expect(layouts().find((l) => l.slug === "elden-ring").pack.id).toBe("com.scrthq.runlog.elden-ring-tarnishedtool");
114	  });
115	
116	  describe("the Elden Ring profile", () => {
117	    const setups = ["bare-handed", "brute", "cleric", "glass", "long-night", "sorcerer", "well-armed"];
118	
119	    /** Every action on every page of a built profile. */
120	    const placed = (built) =>
121	      Object.values(built.files)
122	        .filter((file) => file.Controllers)
123	        .flatMap((file) => file.Controllers.flatMap((c) => Object.values(c.Actions ?? {})));
124	
125	    for (const device of Object.keys(DEVICES)) {
126	      it(`carries the pack's own loadouts on a ${device}`, () => {
127	        const built = all.find(({ spec }) => spec.slug === "elden-ring" && spec.device === device).built;
128	        const settings = placed(built).map((a) => a.Settings);
129	        const chosen = settings.filter((s) => s.setup).map((s) => s.setup.id);
130	        // By id rather than by count: a setup that stopped naming this
131	        // tool would otherwise vanish unremarked.
132	        for (const id of setups) expect(chosen).toContain(`com.scrthq.runlog.setups.${id}`);
133	        // Start of the DLC warps the player, so it is a Command key rather
134	        // than an Apply-setup one.
135	        expect(settings.filter((s) => s.command).map((s) => s.command.id)).toEqual(["com.scrthq.runlog.setups.start-of-the-dlc"]);
136	      });
137	    }
138	  });
139	});

